using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using System.Reflection;
using UnityEngine;

// Opt-in capture harness for the Claude and Muse implementations. Ordinary builds never attach it.
// Initial positions, inventories and passive target durability are fixtures set before each take.
// Inside each take movement, attacks, reloads, consumption and placement use the game's input source.
public partial class CommonMechanicsSuite : Showcase, IPlayerInputSource {
 static string[] Args=>Environment.GetCommandLineArgs();
 static string Arg(string k,string fallback=""){int i=Array.IndexOf(Args,k);return i>=0&&i+1<Args.Length?Args[i+1]:fallback;}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
 static void Load(){if(Array.IndexOf(Args,"-mechanicsSuite")>=0)new GameObject("Mechanics capture loader").AddComponent<MechanicsLoader>();}
 public class MechanicsLoader:MonoBehaviour {
  IEnumerator Start(){PlayerController p=null;while(p==null||p.moves==null){p=FindFirstObjectByType<PlayerController>();yield return null;}var s=gameObject.AddComponent<CommonMechanicsSuite>();s.pc=p;p.source=s;}
 }
 static int HitCount => (int)(typeof(Combatant).GetField("Hits",BindingFlags.Public|BindingFlags.Static)?.GetValue(null)??0);
 string root,model,filter,title="",step=""; MechanicsCapture capture; Vector3 site; Combatant target; bool reload,map;
 Evidence evidence; readonly HashSet<string> observed=new HashSet<string>(); float lastHealth;int startHits,startBuilt,startHarvest;
 [Serializable] public class Evidence {public string id,title,model,status="captured-unreviewed",file,setup="Isolated demonstration. No active opponents. Initial placement and supplies are fixtures; actions use normal player input.",notes;public string[] states;public int frames,hits,pieces,harvest;public float seconds,healthBefore,healthAfter,shieldAfter,targetDamage;}
 public new PlayerInputState Read(){var s=base.Read();s.reload=reload;s.map=map;reload=map=false;return s;}
 void LateUpdate(){if(evidence==null||!capture.Recording)return;observed.Add("mode:"+pc.mode);if(pc.moves.crouched)observed.Add("crouch");if(pc.moves.sliding)observed.Add("slide");if(pc.moves.swimming)observed.Add("swim");if(pc.moves.mantling)observed.Add("mantle");if(pc.aiming)observed.Add("aim");if(pc.hands.Reloading)observed.Add("reload");if(pc.hands.Using)observed.Add("consume");if(pc.sprinting)observed.Add("sprint");if(pc.Motion>0.5f)observed.Add("move");if(pc.emoting>=0)observed.Add("emote:"+pc.emoting);}
 void OnGUI(){} // Capture labels belong on the gallery page, never in game footage.
 bool Wants(string id)=>string.IsNullOrEmpty(filter)||filter.Split(',').Any(x=>id.StartsWith(x));
 bool Done(string id)=>File.Exists(Path.Combine(root,id+".capture.json"));
 IEnumerator Take(string id,string label,IEnumerator action,string notes=""){
  if(!Wants(id)||Done(id))yield break;
  title=label;step="Opening hold";evidence=new Evidence{id=id,title=label,model=model,file=id+".mp4",notes=notes,healthBefore=pc.me.health};observed.Clear();startHits=HitCount;startBuilt=Destructible.Built.Count;startHarvest=Destructible.MatsHarvested;lastHealth=target?target.health:0;
  capture.Begin(Path.Combine(root,id+".mp4"),30);yield return Wait(3);yield return MechanicsSafe.Run(action,e=>{evidence.status="failed";evidence.notes+=" CAPTURE ACTION ERROR: "+e.Message;Debug.LogError(e);});
  _move=Vector2.zero;_sprint=_hold=_aim=false;step="Closing hold";yield return Wait(4);yield return capture.Finish();
  evidence.frames=capture.Frames;evidence.seconds=capture.Frames/30f;evidence.states=observed.OrderBy(x=>x).ToArray();evidence.hits=HitCount-startHits;evidence.pieces=Destructible.Built.Count-startBuilt;evidence.harvest=Destructible.MatsHarvested-startHarvest;evidence.healthAfter=pc.me.health;evidence.shieldAfter=pc.me.shield;evidence.targetDamage=target?lastHealth-target.health:lastHealth;
  File.WriteAllText(Path.Combine(root,id+".evidence.json"),JsonUtility.ToJson(evidence,true));Debug.Log("MECHANIC_DONE "+id+" "+JsonUtility.ToJson(evidence));evidence=null;
 }
 void ResetInput(){_move=Vector2.zero;_look=null;_sprint=_aim=_hold=_tap=_jump=_crouch=_edit=_interact=false;reload=map=false;_slot=0;_build=-1;pc.hands.CancelAction();pc.showMap=false;}
 void Stage(Vector3 p,float yaw=0){Match.I.storm.firstAt=Match.I.Now+600;ResetInput();if(pc.mode==PlayerController.Mode.Bus)typeof(PlayerController).GetMethod("LeaveBus",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(pc,null);pc.StartOnGround();pc.cc.enabled=true;if(pc.glider)pc.glider.SetActive(false);pc.Teleport(new Vector3(p.x,Ground(p)+.12f,p.z),yaw);pc.me.health=100;pc.me.shield=100;pc.stamina=1;pc.me.inv=new Inventory();for(int i=0;i<3;i++)pc.me.inv.AddMats((BuildMat)i,500);pc.hands.Select(0);pc.hands.Refresh();_look=Feet+Quaternion.Euler(0,yaw,0)*Vector3.forward*40+Vector3.up*.7f;}
 void Equip(string id){pc.me.inv.slots[0]=Item.Weapon(WeaponTable.Get(id),Rarity.Rare);foreach(AmmoType a in Enum.GetValues(typeof(AmmoType)))pc.me.inv.AddAmmo(a,500);_slot=1;pc.hands.Select(1);}
 Vector3 FindSite(){for(int x=-170;x<=170;x+=12)for(int z=-170;z<=170;z+=12){var p=new Vector3(x,0,z);if(Ground(p)<3||!Traversal.Dry(p)||!Traversal.Flat(p,14)||!Traversal.Free(p,12,6))continue;p.y=Ground(p);return p;}return new Vector3(76,Ground(new Vector3(76,0,-128)),-128);}
 void SpawnTarget(Vector3 p){if(target)Destroy(target.gameObject);var go=Instantiate(GameAssets.I.botPrefabs[0],new Vector3(p.x,Ground(p)+.1f,p.z),Quaternion.Euler(0,180,0));var bot=go.GetComponent<BotController>();if(bot){bot.me.hands.owner=bot.me;bot.enabled=false;bot.StartOnGround(go.transform.position,180);bot.enabled=false;}foreach(var a in go.GetComponentsInChildren<UnityEngine.AI.NavMeshAgent>())a.enabled=false;target=go.GetComponent<Combatant>();target.inMatch=true;target.health=target.maxHealth=20000;target.shield=0;target.displayName="PASSIVE RECORDING TARGET";target.damageTakenMult=1;}
 protected override IEnumerator Script(){
  root=Arg("-mechanicsOutput");model=Arg("-mechanicsModel","CLAUDE");filter=Arg("-mechanicsTopics");Directory.CreateDirectory(root);capture=gameObject.AddComponent<MechanicsCapture>();Application.runInBackground=true;QualitySettings.vSyncCount=0;Application.targetFrameRate=60;Settings.Temporary=true;
  foreach(var b in FindObjectsByType<BotController>(FindObjectsSortMode.None))b.enabled=false;foreach(var d in FindObjectsByType<SupplyDrops>(FindObjectsSortMode.None))d.enabled=false;FindFirstObjectByType<Hud>()?.ShowHelp(0);
  yield return Wait(1);site=FindSite();Debug.Log("MECHANICS_SITE "+site);
  if(Wants("deployment")&&!Done("deployment")){yield return Take("deployment","Airship departure, dive and glider",Deployment());}
  Match.I.enabled=false;Match.I.phase=Match.Phase.Playing;
  foreach(var w in WeaponTable.All.Where(w=>w.kind!=FireKind.Melee)){var id="weapon_"+w.id;if(!Wants(id)||Done(id))continue;Stage(site);Equip(w.id);SpawnTarget(site+Vector3.forward*(w.id=="shotgun"?9:24));yield return Wait(1);yield return Take(id,w.label+" / handling, fire and reload",Weapon(w),"Passive target starts with 20,000 HP so repeated normal-damage shots can be filmed continuously. No targeting or firing AI.");}
  if(target){Destroy(target.gameObject);target=null;}
  if(Wants("movement")&&!Done("movement")){Stage(site);Equip("assault_rifle");yield return Wait(1);yield return Take("movement","Locomotion / walk, run, sprint, jump, crouch, slide",Movement());}
  if(Wants("building")&&!Done("building"))yield return RecordBuildingVariants();
  foreach(BuildMat mat in Enum.GetValues(typeof(BuildMat))){string id="harvesting_"+mat.ToString().ToLowerInvariant();if(!Wants(id)||Done(id))continue;var props=Destructible.Harvestables.Where(d=>d&&d.Alive&&d.mat==mat&&Ground(d.Center)>3).OrderBy(d=>Vector3.Distance(d.Center,site)).Take(8).ToArray();if(props.Length==0)continue;var d=props[0];var away=Vector3.back;Stage(d.Center+away*4);yield return Wait(1);yield return Take(id,"Pickaxe / "+mat+" and weak points",Harvest(props));}
  foreach(var c in WeaponTable.Consumables){string id="item_"+c.id;if(!Wants(id)||Done(id))continue;Stage(site);pc.me.health=35;pc.me.shield=0;pc.me.inv.slots[0]=Item.Consumable(c,Mathf.Min(3,c.maxStack));pc.hands.Select(1);_slot=1;yield return Wait(1);yield return Take(id,c.label,Consumable(c));}
  if(Wants("emotes")&&!Done("emotes")){Stage(site);yield return Wait(1);yield return Take("emotes","All six emotes / complete loops",Emotes());}
  if(Wants("swimming")&&!Done("swimming")){var p=FindWater();Stage(p);pc.Teleport(new Vector3(p.x,Water.Surface(p,out var wy)?wy-.5f:Ground(p),p.z),0);yield return Wait(1);yield return Take("swimming","Swimming / idle, forward, sprint and turns",Swimming());}
  if(Wants("zipline")&&!Done("zipline")){var z=ZipLine.All.OrderByDescending(z=>z.Length).FirstOrDefault();if(z){var hi=z.a.y>z.b.y?z.a:z.b;var lo=z.a.y>z.b.y?z.b:z.a;var dir=(lo-hi);dir.y=0;dir.Normalize();Stage(hi+dir*.7f,Mathf.Atan2(dir.x,dir.z)*Mathf.Rad2Deg);yield return Wait(1);yield return Take("zipline","Zipline / mount, full ride and arrival",ZipRide(z,lo,dir));}}
  yield return RunExtras();
  File.WriteAllText(Path.Combine(root,"batch-complete.txt"),DateTime.UtcNow.ToString("O"));yield return Finish("MECHANICS_BATCH_COMPLETE "+model);
 }
 IEnumerator Deployment(){step="Airship flyover";yield return Wait(5);_jump=true;step="Jump and freefall";yield return Wait(3);_sprint=true;yield return Wait(1.5f);_sprint=false;_jump=true;step="Glider / steering";_move=new Vector2(.25f,.4f);yield return Wait(12);_move=Vector2.zero;yield return Until(()=>pc.mode==PlayerController.Mode.Ground,35);yield return Wait(4);}
 IEnumerator Weapon(WeaponDef w){step="Idle / weapon grip";_look=target.Chest;yield return Wait(2);step="Walk and strafe";_move=new Vector2(.5f,0);yield return Wait(2);_move=new Vector2(-.5f,0);yield return Wait(2);_move=Vector2.zero;step="Run with weapon";_move=new Vector2(1,0);_sprint=true;yield return Wait(1.2f);_move=new Vector2(-1,0);yield return Wait(1.2f);_move=Vector2.zero;_sprint=false;yield return Wait(1);
  step="Hip fire";for(int i=0;i<(w.kind==FireKind.Grenade?1:3);i++){_tap=true;yield return Wait(Mathf.Max(.35f,w.interval+.15f));}yield return Wait(2);step="Aim and controlled fire";_aim=w.CanAim;yield return Wait(1.5f);for(int i=0;i<(w.kind==FireKind.Grenade?1:3);i++){_tap=true;yield return Wait(Mathf.Max(.4f,w.interval+.2f));}yield return Wait(2);_aim=false;if(w.CanReload){step="Full reload";reload=true;yield return Wait(w.reload+1.3f);}step="Crouch and fire";_crouch=true;yield return Wait(1);_tap=true;yield return Wait(2);_crouch=true;yield return Wait(1);if(w.CanReload){step="Reload and settle";reload=true;yield return Wait(w.reload+1);}else yield return Wait(5);
 }
 IEnumerator Movement(){step="Idle";yield return Wait(3);step="Walk";_move=new Vector2(0,.35f);yield return Wait(4);step="Run";_move=new Vector2(0,1);yield return Wait(4);step="Sprint";_sprint=true;yield return Wait(3);step="Slide and return to crouch";_crouch=true;yield return Wait(2.5f);_move=Vector2.zero;_sprint=false;yield return Wait(2);step="Crouch walk";if(!pc.moves.crouched)_crouch=true;_move=new Vector2(.5f,0);yield return Wait(3);_move=new Vector2(-.5f,0);yield return Wait(3);_move=Vector2.zero;_crouch=true;yield return Wait(1);step="Jump / complete landing";_jump=true;yield return Wait(3);_move=new Vector2(0,-.5f);yield return Wait(4);_move=Vector2.zero;_jump=true;yield return Wait(3);}
 IEnumerator Building(){for(int mat=0;mat<3;mat++)for(int kind=0;kind<4;kind++){step=((BuildMat)mat)+" / "+((PieceType)kind)+" / preview and placement";_look=Feet+Vector3.forward*40+Vector3.up*.6f;_build=kind;yield return Wait(.6f);for(int n=0;n<3&&(int)pc.buildMat!=mat;n++){_aimTap=true;yield return Wait(.15f);}yield return Wait(1);_tap=true;yield return Wait(BuildRules.BuildTime((BuildMat)mat)+.5f);_slot=0;yield return Wait(.2f);_move=new Vector2(1,0);yield return Wait(2.2f);_move=Vector2.zero;yield return Wait(.7f);}step="Finished pieces";_look=Feet+Vector3.left*30+Vector3.up*2;yield return Wait(5);}
 IEnumerator Harvest(Destructible[] props){foreach(var d in props.Take(3)){if(!d||!d.Alive)continue;step="Approach "+d.name;_look=d.Center;yield return WalkTo(d.Center,1.5f,10);_look=new Vector3(d.Center.x,Feet.y+1.1f,d.Center.z);yield return Wait(1);step="Pickaxe / blue weak point";for(int i=0;i<12&&d&&d.Alive;i++){if(d.lastHitBy==pc.me&&Time.time<d.weakUntil)_look=d.weakPoint;yield return Wait(.4f);_tap=true;yield return Wait(.8f);}yield return Wait(3);} }
 IEnumerator Consumable(ConsumableDef c){step="Item in hands";yield return Wait(3);step="Use / full animation";_tap=true;yield return Wait(c.useTime+2);if(c.action=="pad"){step="Walk onto placed pad";_move=Vector2.up;yield return Until(()=>pc.mode==PlayerController.Mode.Skydive,5);_move=new Vector2(.5f,1);yield return Wait(15);_move=Vector2.zero;yield return Until(()=>pc.mode==PlayerController.Mode.Ground,20);}else if(c.action=="rift"){step="Rift departure and glide";_move=new Vector2(.3f,.5f);yield return Wait(18);_move=Vector2.zero;yield return Until(()=>pc.mode==PlayerController.Mode.Ground,30);}else{step="HUD recovery result";yield return Wait(5);if(c.id=="bandage"){step="Second use";_tap=true;yield return Wait(c.useTime+2);}yield return Wait(6);} }
 IEnumerator Emotes(){_look=null;for(int i=0;i<GameAssets.Emotes.Length;i++){step=GameAssets.EmoteLabels[i];_emote=i+1;yield return Wait(14);_move=new Vector2(.1f,0);yield return Wait(.2f);_move=Vector2.zero;yield return Wait(1.5f);}}
 Vector3 FindWater(){for(int z=-150;z<150;z+=4)for(int x=-140;x<140;x+=4){var p=new Vector3(x,0,z);if(Water.Surface(p,out var y)&&y-Ground(p)>2.5f){bool good=true;for(int k=-10;k<=20;k+=5){var q=p+Vector3.forward*k;if(!Water.Surface(q,out var yy)||yy-Ground(q)<1.6f)good=false;}if(good)return p;}}return new Vector3(0,0,0);}
 IEnumerator Swimming(){step="Tread water";yield return Wait(5);step="Swim forward";_move=Vector2.up;yield return Wait(5);step="Fast swim";_sprint=true;yield return Wait(4);_sprint=false;_move=Vector2.zero;yield return Wait(3);step="Turn and return";_look=Feet+Vector3.back*50+Vector3.up;yield return Wait(2);_move=Vector2.up;yield return Wait(8);_move=Vector2.zero;yield return Wait(4);}
 IEnumerator ZipRide(ZipLine z,Vector3 lo,Vector3 dir){_look=lo+Vector3.up*2;yield return Wait(2);step="Interact / mount";_interact=true;yield return Until(()=>pc.mode==PlayerController.Mode.Zip,2);step="Full cable ride";_look=lo+dir*20+Vector3.up;yield return Until(()=>pc.mode!=PlayerController.Mode.Zip,25);step="Arrival";yield return Wait(6);_move=Vector2.up;yield return Wait(3);_move=Vector2.zero;yield return Wait(4);}
}
